    ExecutorService es = Executors.newFixedThreadPool(2);
    CountDownLatch latch = new CountDownLatch(2);

    for (int i = 0; i < 2; i++) {
        es.submit(() -> {
            try {
                Member m = new Member();
                m.setName("kim");
                memberService.join(m);
            } catch (Exception e) {
                log.info("실패 = {}", e.getMessage());
            } finally {
                latch.countDown();
            }
        });
    }
    latch.await();
}

